export const taDeviVerses2: MeaningPack = {
  lang: 'ta',
  texts: {
    'devi-mahatmyam-05': {
      verses: {
        '0.0': "ஓம். இந்த உத்தர சரித்திரத்துக்கு ரிஷி ருத்திரன், தேவதை மகாஸரஸ்வதீ, சந்தஸ் அனுஷ்டுப், சக்தி பீமா, பீஜம் ப்ராமரீ, தத்துவம் சூரியன், ஸ்வரூபம் ஸாமவேதம்; மகாஸரஸ்வதியின் ப்ரீதிக்காக உத்தர சரித்திர பாராயணத்தில் இதன் விநியோகம்.",
        '0.1': "ஓம். தாமரைக் கரங்களில் மணி, சூலம், கலப்பை, சங்கு, உலக்கை, சக்கரம், வில், அம்பு ஏந்தியவளும், மழைக்கால முடிவில் ஒளிரும் சந்திரனைப் போன்ற ஒளியுடையவளும், கௌரியின் உடலிலிருந்து தோன்றியவளும், மூவுலகுக்கும் ஆதாரமானவளும், சும்பன் முதலிய அசுரர்களை அழித்தவளுமான மகாஸரஸ்வதியை இங்கே தியானிக்கிறேன்.",
        '1.0': "ரிஷி கூறினார்:",
        '1.1': "முன்னொரு காலத்தில் சும்ப நிசும்பர் என்னும் அசுரர்கள் தம் செருக்கையும் வலிமையையும் சார்ந்து, சசீபதியான இந்திரனிடமிருந்து மூவுலகையும் யக்ஞ பாகங்களையும் பறித்துக்கொண்டனர்.",
        '1.2': "அவ்விருவருமே சூரியனின் அதிகாரத்தையும், அவ்வாறே சந்திரன், குபேரன், யமன், வருணன் ஆகியோரின் அதிகாரங்களையும் ஏற்றுக்கொண்டனர்.",
        '1.3': "அவர்களே வாயுவின் வளத்தையும் அக்னியின் பணியையும் ஏற்றனர். அப்போது தேவர்கள் துரத்தப்பட்டு, தோற்று, அரசிழந்து,",
        '1.4': "அவ்விரு மகாசுரர்களால் அதிகாரம் பறிக்கப்பட்டு எல்லோரும் விரட்டப்பட்டு, வெல்லப்பட முடியாத அந்தத் தேவியை நினைத்தனர்.",
        '1.5': "(அவர்கள் எண்ணினர்:) “‘ஆபத்துகளில் என்னை நினைக்கும்போது அக்கணமே உங்கள் பெரும் ஆபத்துகள் அனைத்தையும் அழிப்பேன்’ என்று அவள் நமக்கு வரம் தந்திருக்கிறாள்.”",
        '1.6': "இவ்வாறு தீர்மானித்துத் தேவர்கள் மலைகளின் அரசனான இமயத்துக்குச் சென்று, அங்கே விஷ்ணுமாயையான தேவியைத் துதித்தனர்.",
        '2.0': "தேவர்கள் கூறினர்:",
        '2.1': "தேவிக்கு, மகாதேவிக்கு நமஸ்காரம்; மங்கள வடிவான சிவைக்கு எப்போதும் நமஸ்காரம். பிரக்ருதிக்கு, பத்ரைக்கு நமஸ்காரம். அடக்கத்துடன் நாங்கள் அவளை வணங்குகிறோம்.",
        '2.2': "ரௌத்ரிக்கு, நித்யைக்கு, கௌரிக்கு, தாத்ரிக்கு மீண்டும் மீண்டும் நமஸ்காரம்; நிலவொளியானவளுக்கு, சந்திர வடிவினளுக்கு, இன்ப வடிவினளுக்கு எப்போதும் நமஸ்காரம்.",
        '2.3': "வணங்குவோருக்கு வளர்ச்சியும் வெற்றியுமான கல்யாணியை மீண்டும் மீண்டும் வணங்குகிறோம். நைர்ருதியும், அரசர்களின் லக்ஷ்மியும், சர்வாணியுமான உனக்கு மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.4': "துன்பங்களைக் கடக்கச் செய்யும் துர்கைக்கு, சாரமானவளுக்கு, எல்லாவற்றையும் செய்பவளுக்கு, க்யாதிக்கு, அவ்வாறே க்ருஷ்ணைக்கும் தூம்ரைக்கும் எப்போதும் நமஸ்காரம்.",
        '2.5': "மிக மென்மையானவளும் மிகக் கடுமையானவளுமான அவளுக்குத் தலைவணங்கி மீண்டும் மீண்டும் நமஸ்கரிக்கிறோம். உலகுக்கு ஆதாரமானவளும் செயல் வடிவினளுமான தேவிக்கு மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.6': "எல்லா உயிர்களிலும் விஷ்ணுமாயை என்று அழைக்கப்பட்டு நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.7': "எல்லா உயிர்களிலும் சேதனை (உணர்வு) என்று அழைக்கப்பட்டு நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.8': "எல்லா உயிர்களிலும் புத்தியின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.9': "எல்லா உயிர்களிலும் உறக்கத்தின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.10': "எல்லா உயிர்களிலும் பசியின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.11': "எல்லா உயிர்களிலும் நிழலின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.12': "எல்லா உயிர்களிலும் சக்தியின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.13': "எல்லா உயிர்களிலும் தாகத்தின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.14': "எல்லா உயிர்களிலும் பொறுமையின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.15': "எல்லா உயிர்களிலும் பிறப்பின் (ஜாதியின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.16': "எல்லா உயிர்களிலும் நாணத்தின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.17': "எல்லா உயிர்களிலும் அமைதியின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.18': "எல்லா உயிர்களிலும் சிரத்தையின் (நம்பிக்கையின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.19': "எல்லா உயிர்களிலும் காந்தியின் (ஒளியின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.20': "எல்லா உயிர்களிலும் லக்ஷ்மியின் (செல்வத்தின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.21': "எல்லா உயிர்களிலும் வாழ்வுத் தொழிலின் (வ்ருத்தியின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.22': "எல்லா உயிர்களிலும் நினைவின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.23': "எல்லா உயிர்களிலும் கருணையின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.24': "எல்லா உயிர்களிலும் மனநிறைவின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.25': "எல்லா உயிர்களிலும் தாயின் வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.26': "எல்லா உயிர்களிலும் மயக்கத்தின் (பிராந்தியின்) வடிவில் நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.27': "உயிர்களின் புலன்களை ஆள்பவளும், எல்லா உயிர்களிலும் எப்போதும் நிறைந்திருப்பவளுமான வ்யாப்தி தேவிக்கு மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.28': "சித் (உணர்வு) வடிவில் இந்த உலகம் முழுவதையும் வியாபித்து நிலைத்திருக்கும் தேவிக்கு நமஸ்காரம், நமஸ்காரம், நமஸ்காரம், மீண்டும் மீண்டும் நமஸ்காரம்.",
        '2.29': "முன்பு விருப்பம் நிறைவேறத் தேவர்களால் துதிக்கப்பட்டவளும், தேவேந்திரனால் நாள்தோறும் வழிபடப்பட்டவளும், நலத்துக்குக் காரணமானவளுமான அந்த ஈச்வரி எங்களுக்கு நன்மையும் மங்களமும் செய்யட்டும்; எங்கள் ஆபத்துகளை அழிக்கட்டும்.",
        '2.30': "செருக்குற்ற அசுரர்களால் துன்புறுத்தப்பட்ட தேவர்களான எங்களால் இப்போது வணங்கப்படுபவளும், பக்தியால் பணிந்தோர் நினைத்த கணமே எங்கள் ஆபத்துகள் அனைத்தையும் அழிப்பவளுமான அந்த ஈச்வரி (எங்களைக் காக்கட்டும்).",
        '3.0': "ரிஷி கூறினார்:",
        '3.1': "அரசகுமாரனே, தேவர்கள் இவ்வாறு துதித்துக்கொண்டிருந்தபோது பார்வதி ஜாஹ்னவியின் (கங்கையின்) நீரில் நீராட அங்கே வந்தாள்.",
        '3.2': "அழகிய புருவமுடைய அவள் தேவர்களிடம் “இங்கே நீங்கள் யாரைத் துதிக்கிறீர்கள்?” என்று கேட்டாள். அப்போது அவள் உடலின் கோசத்திலிருந்து வெளிப்பட்ட சிவை கூறினாள்:",
        '3.3': "“சும்ப அசுரனால் விரட்டப்பட்டு, போரில் நிசும்பனால் தோற்கடிக்கப்பட்டு ஒன்றுகூடிய தேவர்கள் இந்தத் துதியை எனக்கே செய்கின்றனர்.”",
        '3.4': "பார்வதியின் உடல் கோசத்திலிருந்து அம்பிகை வெளிப்பட்டதால், எல்லா உலகங்களிலும் அவள் ‘கௌசிகீ’ என்று போற்றப்படுகிறாள்.",
        '3.5': "அவள் வெளிப்பட்டதும் அந்தப் பார்வதியும் கருநிறமானாள்; இமயத்தில் வசிக்கும் அவள் ‘காளிகா’ என்று புகழ்பெற்றாள்.",
        '3.6': "அப்போது சும்ப நிசும்பரின் பணியாளர்களான சண்டனும் முண்டனும் மிக மனங்கவரும் மேலான வடிவம் தாங்கிய அம்பிகையைக் கண்டனர்.",
        '3.7': "அவர்கள் சும்பனிடம் கூறினர்: “மகாராஜா, மிக அழகிய ஒரு பெண் இமயத்தை ஒளிரச் செய்தவாறு அங்கே இருக்கிறாள்.”",
        '3.8': "“அத்தகைய உயர்ந்த அழகை எங்கும் எவரும் கண்டதில்லை. அசுரேச்வரனே, அந்தத் தேவி யார் என்று அறிந்து அவளைக் கைக்கொள்.”",
        '3.9': "“அசுர அரசே, மிக அழகிய அங்கங்களுடைய, தன் ஒளியால் திசைகளை ஒளிரச் செய்யும் அந்தப் பெண்களில் ரத்தினம் அங்கே இருக்கிறாள்; நீ அவளைக் காண வேண்டும்.”",
        '3.10': "“பிரபுவே, மூவுலகிலும் உள்ள ரத்தினங்கள், மணிகள், யானைகள், குதிரைகள் முதலிய அனைத்தும் இப்போது உன் இல்லத்தில் ஒளிர்கின்றன.”",
        '3.11': "“யானைகளில் ரத்தினமான ஐராவதம் இந்திரனிடமிருந்து கொண்டுவரப்பட்டது; அவ்வாறே இந்தப் பாரிஜாத மரமும் உச்சைச்ரவஸ் என்னும் குதிரையும்.”",
        '3.12': "“பிரம்மாவுக்கு உரியதாக இருந்த, அன்னங்கள் பூட்டிய அற்புதமான ரத்தினம் போன்ற இந்த விமானம் இங்கே கொண்டுவரப்பட்டு உன் முற்றத்தில் நிற்கிறது.”",
        '3.13': "“மகாபத்மம் என்னும் இந்த நிதி செல்வத்தின் தலைவனான குபேரனிடமிருந்து கொண்டுவரப்பட்டது; கடல் மகரந்தமுள்ள வாடாத தாமரை மாலையைத் தந்தது.”",
        '3.14': "“பொன்னைப் பொழியும் வருணனின் குடை உன் இல்லத்தில் இருக்கிறது; முன்பு பிரஜாபதிக்கு உரியதாக இருந்த இந்தச் சிறந்த தேரும் இருக்கிறது.”",
        '3.15': "“ஈசனே, மிருத்யுவின் ‘உத்க்ராந்திதா’ என்னும் சக்தி ஆயுதத்தை நீ பறித்துக்கொண்டாய்; நீரின் அரசனான வருணனின் பாசம் உன் தம்பியின் வசம் இருக்கிறது.”",
        '3.16': "“கடலில் பிறந்த எல்லா வகை ரத்தினங்களும் நிசும்பனுடையவை; அக்னியும் நெருப்பால் தூய்மையான இரண்டு ஆடைகளை உனக்குத் தந்தான்.”",
        '3.17': "“அசுர அரசே, இவ்வாறு எல்லா ரத்தினங்களும் உனக்குக் கொண்டுவரப்பட்டுள்ளன. மங்களமான இந்தப் பெண்களில் ரத்தினத்தை நீ ஏன் கைக்கொள்ளவில்லை?”",
        '3.18': "ரிஷி கூறினார்:",
        '3.19': "சண்ட முண்டரின் இச்சொற்களைக் கேட்டுச் சும்பன் அப்போது ஸுக்ரீவன் என்னும் மகாசுரனைத் தூதனாகத் தேவியிடம் அனுப்பினான்.",
        '3.20': "“சென்று என் சொல்லாக அவளிடம் இன்னின்னவாறு கூறு; அவள் மகிழ்வுடன் வரும்படி விரைவில் செயல்படு.”",
        '3.21': "அவன் மலையின் மிக அழகிய இடத்தில் அவள் இருந்த இடத்துக்குச் சென்று, மென்மையான இனிய சொற்களால் தேவியிடம் பேசினான்.",
        '3.22': "தூதன் கூறினான்:",
        '3.23': "“தேவியே, அசுரர் தலைவனான சும்பன் மூவுலகுக்கும் பரமேச்வரன். அவனால் அனுப்பப்பட்ட தூதனான நான் உன்னிடம் இங்கே வந்துள்ளேன்.”",
        '3.24': "“எல்லா தேவ இனங்களிலும் எவனுடைய கட்டளை எப்போதும் தடையின்றி நடக்கிறதோ, அசுரர்களின் பகைவர் அனைவரையும் எவன் வென்றானோ, அவன் சொல்வதைக் கேள்.”",
        '3.25': "“(சும்பன் கூறுகிறான்:) மூவுலகம் முழுதும் என்னுடையது; தேவர்கள் என் வசத்தில் உள்ளனர். யக்ஞ பாகங்கள் அனைத்தையும் தனித்தனியே நானே அனுபவிக்கிறேன்.”",
        '3.26': "“மூவுலகின் சிறந்த ரத்தினங்கள் அனைத்தும் முழுமையாக என் வசம் உள்ளன; அவ்வாறே தேவேந்திரனின் வாகனமான யானை ரத்தினத்தையும் நான் கவர்ந்தேன்.”",
        '3.27': "“பாற்கடலைக் கடைந்தபோது பிறந்த உச்சைச்ரவஸ் என்னும் குதிரை ரத்தினத்தை அமரர்கள் வணங்கி எனக்கு ஒப்படைத்தனர்.”",
        '3.28': "“அழகியே, தேவர்கள், கந்தர்வர்கள், நாகர்களிடையே ரத்தினம் போன்ற மற்றப் பொருள்கள் அனைத்தும் என்னிடமே உள்ளன.”",
        '3.29': "“தேவியே, உலகில் உன்னைப் பெண்களில் ரத்தினமாக நாங்கள் கருதுகிறோம். ரத்தினங்களை அனுபவிப்பவர்கள் நாங்களே என்பதால் நீ எங்களிடம் வா.”",
        '3.30': "“அலையும் கடைக்கண் பார்வையுடையவளே, நீ உண்மையில் ரத்தினமானவள் என்பதால் என்னையோ, பெரும் வீரனான என் தம்பி நிசும்பனையோ மணந்துகொள்.”",
        '3.31': "“என்னை மணப்பதால் ஒப்பற்ற பேரரசுச் செல்வத்தைப் பெறுவாய். இதை அறிவால் நன்கு ஆராய்ந்து என் மனைவியாகு.”",
        '3.32': "ரிஷி கூறினார்:",
        '3.33': "இவ்வாறு கூறப்பட்டபோது, இந்த உலகைத் தாங்குபவளும் பகவதியும் பத்ரையுமான துர்கா தேவி உள்ளுக்குள் புன்னகைத்துக் கம்பீரமாகக் கூறினாள்.",
        '3.34': "தேவி கூறினாள்:",
        '3.35': "“நீ உண்மையையே கூறினாய்; இதில் சிறிதும் பொய் சொல்லவில்லை. சும்பன் மூவுலகின் தலைவன்; நிசும்பனும் அத்தகையவனே.”",
        '3.36': "“ஆனால் இவ்விஷயத்தில் நான் செய்த சபதத்தை எவ்வாறு பொய்யாக்குவேன்? சிற்றறிவால் முன்பு நான் செய்த சபதத்தைக் கேள்.”",
        '3.37': "“எவன் போரில் என்னை வெல்கிறானோ, எவன் என் செருக்கை அகற்றுகிறானோ, உலகில் எவன் எனக்கு நிகரான வலிமையுடையவனோ, அவனே என் கணவனாவான்.”",
        '3.38': "“ஆகவே சும்பனோ மகாசுரனான நிசும்பனோ இங்கே வரட்டும். என்னை வென்று விரைவில் என் கரம் பற்றட்டும்; தாமதம் ஏன்?”",
        '3.39': "தூதன் கூறினான்:",
        '3.40': "“தேவியே, நீ செருக்குற்றிருக்கிறாய்; என் முன் இவ்வாறு பேசாதே. மூவுலகிலும் எந்த ஆண் சும்ப நிசும்பர் முன் நிற்க முடியும்?”",
        '3.41': "“தேவியே, மற்ற அசுரர்களின் முன்கூடப் போரில் எல்லாத் தேவர்களும் நிற்க முடியாது; தனியொரு பெண்ணான நீ எம்மாத்திரம்?”",
        '3.42': "“இந்திரன் முதலிய எல்லாத் தேவர்களும் போரில் எவர் முன் நிற்கவில்லையோ, அந்தச் சும்பன் முதலியோர் முன் பெண்ணான நீ எப்படிச் செல்வாய்?”",
        '3.43': "“ஆகவே நான் சொன்னபடி நீயே சும்ப நிசும்பரிடம் செல்; கூந்தலைப் பற்றி இழுக்கப்பட்டு மதிப்பிழந்து செல்லாதே.”",
        '3.44': "தேவி கூறினாள்:",
        '3.45': "“அப்படியே: சும்பன் வலிமையானவன், நிசும்பன் மிகுந்த வீரமுடையவன். ஆனால் நான் என்ன செய்வேன்? ஆராயாமல் முன்பே சபதம் செய்துவிட்டேன்.”",
        '3.46': "“ஆகவே நீ சென்று நான் சொன்னதை எல்லாம் மதிப்புடன் அசுர அரசனிடம் தெரிவி; அவன் தகுந்ததைச் செய்யட்டும்.”",
        '3.47': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “தேவீ-தூத ஸம்வாதம்” என்னும் ஐந்தாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'devi-mahatmyam-06': {
      verses: {
        '0.0': "ஓம். நாகராஜனை ஆசனமாகக் கொண்டவளும், படங்களிலுள்ள பெரிய ரத்தின வரிசையின் ஒளியால் ஒளிரும் கொடி போன்ற உடலுடையவளும், சூரியனைப் போல் ஒளிர்பவளும், மூன்று கண்களால் விளங்குபவளும், ஜபமாலை, கலசம், கபாலம், தாமரை ஆகியவற்றைக் கைகளில் ஏந்தியவளும், பிறைச் சந்திரனை முடியில் அணிந்தவளும், எல்லாம் அறிந்த ஈசனான பைரவனின் மடியில் அமர்ந்தவளுமான பரா தேவி பத்மாவதியைத் தியானிக்கிறேன்.",
        '1.0': "ரிஷி கூறினார்:",
        '1.1': "தேவியின் சொற்களைக் கேட்டுச் சினம் நிறைந்த அந்தத் தூதன் திரும்பி வந்து அசுர அரசனிடம் அனைத்தையும் விரிவாகக் கூறினான்.",
        '1.2': "தூதனின் சொற்களைக் கேட்ட அசுர அரசன் சினத்துடன் அசுரர்களின் தலைவனான தூம்ரலோசனனிடம் கூறினான்:",
        '1.3': "“தூம்ரலோசனா, நீ உன் படையுடன் விரைந்து சென்று, அந்தக் கொடியவளைக் கூந்தலைப் பற்றி இழுத்துக் கலங்கச் செய்து பலவந்தமாகக் கொண்டு வா.”",
        '1.4': "“அவளைக் காக்க வேறு எவனாவது எழுந்தால், அவன் தேவனானாலும் யக்ஷனானாலும் கந்தர்வனானாலும் கொல்லப்பட வேண்டும்.”",
        '1.5': "ரிஷி கூறினார்:",
        '1.6': "இவ்வாறு கட்டளையிடப்பட்ட தூம்ரலோசனன் என்னும் அசுரன் அறுபதாயிரம் அசுரர்கள் சூழ விரைந்து புறப்பட்டான்.",
        '1.7': "பனிமலையில் இருந்த அந்தத் தேவியைக் கண்டு அவன் “சும்ப நிசும்பரிடம் வா” என்று உரக்கக் கூவினான்.",
        '1.8': "“இன்று நீ விருப்பத்துடன் என் தலைவனிடம் வராவிட்டால், கூந்தலைப் பற்றி இழுத்துக் கலங்கச் செய்து பலவந்தமாகக் கொண்டு செல்வேன்.”",
        '1.9': "தேவி கூறினாள்:",
        '1.10': "“அசுரர் தலைவனால் அனுப்பப்பட்டவனும், வலிமையுள்ளவனும், படை சூழ்ந்தவனுமான நீ இவ்வாறு என்னைப் பலவந்தமாகக் கொண்டு சென்றால் நான் உன்னை என்ன செய்ய முடியும்?”",
        '1.11': "ரிஷி கூறினார்:",
        '1.12': "இவ்வாறு கூறப்பட்ட அசுரன் தூம்ரலோசனன் அவளை நோக்கிப் பாய்ந்தான்; அம்பிகை வெறும் ‘ஹும்’ ஒலியாலேயே அவனைச் சாம்பலாக்கினாள்.",
        '1.13': "அப்போது சினமுற்ற அசுரர்களின் பெரும் படை மீது அம்பிகை கூரிய அம்புகளையும் சக்திகளையும் கோடரிகளையும் பொழிந்தாள்.",
        '1.14': "அப்போது தேவியின் வாகனமான சிங்கம் சினத்துடன் பிடரியை உலுக்கி அச்சந்தரும் கர்ஜனை செய்து அசுரப் படை மீது பாய்ந்தது.",
        '1.15': "சில அசுரர்களை அது பாதத்தின் அடியாலும், சிலரை வாயாலும், மற்றும் சில மகாசுரர்களைக் காலால் மிதித்தும் கொன்றது.",
        '1.16': "அந்தச் சிங்கம் சிலரின் வயிறுகளை நகங்களால் கிழித்தது; பாதத்தின் அடியால் மற்றவர்களின் தலைகளைத் துண்டித்தது.",
        '1.17': "மேலும் சிலரின் கைகளும் தலைகளும் அதனால் துண்டிக்கப்பட்டன; பிடரியை உலுக்கியவாறு அது மற்றவர்களின் வயிற்றிலிருந்து குருதியைப் பருகியது.",
        '1.18': "ஒரு கணத்தில் அந்தப் படை முழுவதும் மிகுந்த சினமுற்ற, தேவியின் வாகனமான அந்தப் பெரும் சிங்கத்தால் அழிக்கப்பட்டது.",
        '1.19': "அசுரன் தூம்ரலோசனன் தேவியால் கொல்லப்பட்டான் என்றும், அவன் படை முழுவதும் தேவியின் சிங்கத்தால் அழிக்கப்பட்டது என்றும் கேட்டு,",
        '1.20': "அசுரர் தலைவனான சும்பன் உதடுகள் துடிக்கும் அளவுக்குச் சினமுற்று, சண்டன் முண்டன் என்னும் இரு மகாசுரர்களுக்குக் கட்டளையிட்டான்:",
        '1.21': "“சண்டா, முண்டா, பெரும் படைகள் சூழ அங்கே சென்று அவளை விரைவில் இங்கே கொண்டு வாருங்கள்.”",
        '1.22': "“அவளைக் கூந்தலைப் பற்றி இழுத்தோ கட்டியோ கொண்டு வாருங்கள். போரில் உங்களுக்கு ஐயம் ஏற்பட்டால், எல்லா அசுரர்களும் எல்லா ஆயுதங்களாலும் அவளைக் கொல்லட்டும்.”",
        '1.23': "“அந்தக் கொடியவள் அடிபட்டு, சிங்கம் வீழ்த்தப்பட்டதும், அந்த அம்பிகையைப் பிடித்துக் கட்டி விரைவில் திரும்புங்கள்.”",
        '1.24': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “சும்ப நிசும்பரின் சேனாபதி தூம்ரலோசனன் வதம்” என்னும் ஆறாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'devi-mahatmyam-07': {
      verses: {
        '0.0': "ஓம். ரத்தின பீடத்தில் அமர்ந்து கிளியின் இனிய மொழியைக் கேட்பவளும், கருநீல மேனியளும், ஒரு பாதத்தைத் தாமரையில் வைத்தவளும், பிறைச் சந்திரனை அணிந்தவளும், வீணை மீட்டுபவளும், கல்ஹார மலர் மாலை அணிந்தவளும், ஒளிரும் ரவிக்கையைக் கட்டியவளும், சிவந்த ஆடை உடுத்தவளும், சங்குப் பாத்திரம் ஏந்தியவளும், இனிய மதுவின் மயக்கம் கொண்டவளும், நெற்றியில் திலகத்தால் ஒளிர்பவளுமான மாதங்கியைத் தியானிக்கிறேன்.",
        '1.0': "ரிஷி கூறினார்:",
        '1.1': "அப்போது கட்டளை பெற்ற அந்த அசுரர்கள் சண்ட முண்டரைத் தலைமையாகக் கொண்டு நால்வகைப் படையுடன் ஆயுதங்களை உயர்த்தியவாறு புறப்பட்டனர்.",
        '1.2': "மலையரசனின் பெரிய பொன் சிகரத்தில் சிங்கத்தின் மீது அமர்ந்து புன்னகைக்கும் தேவியை அவர்கள் கண்டனர்.",
        '1.3': "அவளைக் கண்டு அவர்கள் பிடிக்க முனைந்தனர்; சிலர் விற்களை வளைத்தனர், சிலர் வாள்களை ஏந்தினர், மற்றும் சிலர் அவள் அருகே வந்தனர்.",
        '1.4': "அப்போது அம்பிகை அந்தப் பகைவர்கள் மீது கடும் சினம் கொண்டாள்; சினத்தால் அவள் முகம் மையைப் போலக் கருத்தது.",
        '1.5': "சுளித்த புருவங்களால் வளைந்த அவள் நெற்றியிலிருந்து உடனே கோர முகமுடைய, வாளும் பாசமும் ஏந்திய காளி வெளிப்பட்டாள்.",
        '1.6': "அவள் விசித்திரமான கட்வாங்கத்தை ஏந்தி, மனிதத் தலை மாலையை அணிந்து, புலித்தோலை உடுத்து, வற்றிய சதையால் மிகக் கொடூரமாக இருந்தாள்.",
        '1.7': "அவள் வாய் மிக அகன்றிருந்தது; தொங்கும் நாக்கால் அச்சமூட்டினாள்; கண்கள் உட்குழிந்து சிவந்திருந்தன; கர்ஜனையால் திசைகளை நிரப்பினாள்.",
        '1.8': "அவள் வேகமாகப் பாய்ந்து மகாசுரர்களைக் கொன்றவாறு, தேவர்களின் பகைவர்களான அந்தப் படையை விழுங்கினாள்.",
        '1.9': "பின்புறக் காவலர், அங்குசம் ஏந்திய பாகர், வீரர், மணிகள் ஆகியவற்றுடன் யானைகளை ஒரே கையால் எடுத்து அவள் வாயில் எறிந்தாள்.",
        '1.10': "அவ்வாறே குதிரைகளுடன் வீரர்களையும், சாரதியுடன் தேர்களையும் வாயில் இட்டுப் பற்களால் மிகக் கொடூரமாக மென்றாள்.",
        '1.11': "ஒருவனைக் கூந்தலைப் பற்றியும், இன்னொருவனைக் கழுத்தைப் பற்றியும் பிடித்தாள்; வேறொருவனைக் காலால் மிதித்தாள், மற்றொருவனை மார்பால் நசுக்கினாள்.",
        '1.12': "அந்த அசுரர்கள் எறிந்த ஆயுதங்களையும் பேரஸ்திரங்களையும் அவள் சினத்துடன் வாயால் பற்றிப் பற்களால் நொறுக்கினாள்.",
        '1.13': "வலிமையுள்ள தீய அசுரர்களின் அந்தப் படை முழுவதையும் அவள் நசுக்கினாள்; சிலரை விழுங்கினாள், மற்றவர்களை அடித்து வீழ்த்தினாள்.",
        '1.14': "சில அசுரர்கள் வாளால் கொல்லப்பட்டனர், சிலர் கட்வாங்கத்தால் அடிக்கப்பட்டனர், மற்றும் சிலர் பற்களின் நுனியால் கிழிக்கப்பட்டு அழிந்தனர்.",
        '1.15': "ஒரு கணத்தில் அசுரர்களின் அந்தப் படை முழுதும் வீழ்ந்ததைக் கண்டு சண்டன் மிகக் கொடூரமான அந்தக் காளியை நோக்கிப் பாய்ந்தான்.",
        '1.16': "அந்த மகாசுரன் அச்சந்தரும் கண்களுடைய அவளை மிகக் கொடிய அம்பு மழையால் மூடினான்; முண்டன் ஆயிரக்கணக்கில் எறிந்த சக்கரங்களால் மூடினான்.",
        '1.17': "அவள் வாயினுள் நுழைந்த அந்தப் பல சக்கரங்கள் மேகத்தின் வயிற்றுக்குள் நுழையும் பல சூரிய வட்டங்களைப் போல விளங்கின.",
        '1.18': "அப்போது கொடூரமாக முழங்கும் காளி பெருஞ்சினத்துடன் அச்சந்தரச் சிரித்தாள்; அவள் கோர வாயினுள் காண இயலாத பற்கள் ஒளிர்ந்தன.",
        '1.19': "தேவி எழுந்து பெரிய வாளை உயர்த்தி ‘ஹம்’ என்று சண்டனை நோக்கிப் பாய்ந்தாள்; அவன் கூந்தலைப் பற்றி அந்த வாளால் அவன் தலையை வெட்டினாள்.",
        '1.20': "சண்டன் வீழ்ந்ததைக் கண்ட முண்டன் அவளை நோக்கிப் பாய்ந்தான்; அவள் சினத்துடன் வாளால் வெட்டி அவனையும் தரையில் வீழ்த்தினாள்.",
        '1.21': "சண்டனும் பெரும் வீரனான முண்டனும் வீழ்ந்ததைக் கண்டு எஞ்சிய படை அஞ்சித் திசைதோறும் ஓடியது.",
        '1.22': "காளி சண்ட முண்டரின் தலைகளை எடுத்துக்கொண்டு சண்டிகையிடம் வந்து கடும் அட்டகாசச் சிரிப்புடன் கூறினாள்:",
        '1.23': "“சண்டன் முண்டன் என்னும் இரண்டு பெரும் பலிப் பசுக்களை நான் உனக்கு இங்கே கொண்டு வந்துள்ளேன். போர் என்னும் யக்ஞத்தில் சும்ப நிசும்பரை நீயே கொல்வாய்.”",
        '1.24': "ரிஷி கூறினார்:",
        '1.25': "கொண்டு வரப்பட்ட மகாசுரர்களான சண்ட முண்டரைக் கண்டு மங்களமான சண்டிகை காளியிடம் இனிமையாகக் கூறினாள்:",
        '1.26': "“தேவியே, நீ சண்டனையும் முண்டனையும் பிடித்துக் கொண்டு வந்ததால் உலகில் ‘சாமுண்டா’ என்று புகழ்பெறுவாய்.”",
        '1.27': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “சண்ட முண்ட வதம்” என்னும் ஏழாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'devi-mahatmyam-08': {
      verses: {
        '0.0': "ஓம். செந்நிறமானவளும், கருணை அலைபாயும் கண்களுடையவளும், பாசம், அங்குசம், அம்பு, வில் ஆகியவற்றைக் கைகளில் ஏந்தியவளும், அணிமா முதலிய சித்திகள் என்னும் கதிர்களால் சூழப்பட்டவளுமான பவானியை ‘நானே அவள்’ என்ற பாவனையுடன் தியானிக்கிறேன்.",
        '1.0': "ரிஷி கூறினார்:",
        '1.1': "சண்ட அசுரன் கொல்லப்பட்டு, முண்டனும் வீழ்த்தப்பட்டு, பல படைகள் அழிந்தபோது அசுரர் தலைவன் —",
        '1.2': "வலிமைமிக்க சும்பன் சினத்துக்கு அடிமையான மனத்துடன் அசுரர்களின் எல்லாப் படைகளையும் போருக்கு ஆயத்தமாகும்படி கட்டளையிட்டான்.",
        '1.3': "“இன்று ஆயுதம் ஏந்திய எண்பத்தாறு அசுரர்களும், எண்பத்து நான்கு கம்புக்களும் தத்தம் படைகள் சூழ முழு வலிமையுடன் புறப்படட்டும்.”",
        '1.4': "“கோடிவீர்யர் என்னும் ஐம்பது அசுரக் குலங்களும் தௌம்ரர்களின் நூறு குலங்களும் என் ஆணைப்படி புறப்படட்டும்.”",
        '1.5': "“காலகர், தௌர்ஹ்ருதர், மௌர்யர், காலகேயர் என்னும் அசுரர்கள் போருக்கு ஆயத்தமாகி என் ஆணைப்படி விரைந்து புறப்படட்டும்.”",
        '1.6': "இவ்வாறு கட்டளையிட்டு, கொடிய ஆட்சியுடைய அசுர அரசன் சும்பன் ஆயிரக்கணக்கான பெரும் படைகள் சூழப் புறப்பட்டான்.",
        '1.7': "மிகக் கொடிய அந்தப் படை வருவதைக் கண்டு சண்டிகை வில்நாணின் ஓசையால் மண்ணுக்கும் விண்ணுக்கும் இடையிலான வெளியை நிரப்பினாள்.",
        '1.8': "அரசனே, அப்போது சிங்கம் பெரும் கர்ஜனை செய்தது; அம்பிகை மணியோசையால் அந்த ஒலியை மேலும் பெருக்கினாள்.",
        '1.9': "வில்நாண், சிங்கம், மணி ஆகியவற்றின் ஓசையால் திசைகள் நிரம்பியிருக்க, வாயை அகலத் திறந்த காளி தன் கொடிய முழக்கங்களால் அவை அனைத்தையும் விஞ்சினாள்.",
        '1.10': "அந்த ஒலியைக் கேட்டுச் சினமுற்ற அசுரப் படைகள் தேவியையும் சிங்கத்தையும் காளியையும் நான்கு திசைகளிலிருந்தும் சூழ்ந்தன.",
        '1.11': "அரசனே, இதற்கிடையே தேவர்களின் பகைவர் அழிவுக்காகவும், தேவர்களில் சிறந்தோரின் நலனுக்காகவும், மிகுந்த வீரமும் வலிமையும் உடைய —",
        '1.12': "— பிரம்மா, ஈசன், குகன் (ஸ்கந்தன்), விஷ்ணு, இந்திரன் ஆகியோரின் சக்திகள் அவர்கள் உடல்களிலிருந்து வெளிப்பட்டு அவரவர் வடிவங்களில் சண்டிகையிடம் சென்றன.",
        '1.13': "எந்தத் தேவனுக்கு எந்த வடிவமும், அணிகலன்களும், வாகனமும் இருந்தனவோ, அதே விதமாக அவன் சக்தி அசுரர்களுடன் போரிட வந்தது.",
        '1.14': "அன்னங்கள் பூட்டிய விமானத்தில் ஜபமாலையும் கமண்டலமும் ஏந்திப் பிரம்மாவின் சக்தி வந்தாள்; அவள் ‘ப்ரஹ்மாணீ’ எனப்படுகிறாள்.",
        '1.15': "மாஹேச்வரி காளையின் மீது ஏறி, சிறந்த திரிசூலம் ஏந்தி, பெரும் பாம்புகளைக் கடகங்களாக அணிந்து, பிறைச் சந்திரனை அணிகலனாகத் தரித்து வந்தாள்.",
        '1.16': "கையில் வேல் ஏந்தி, சிறந்த மயிலை வாகனமாகக் கொண்டு, குகனின் வடிவம் தாங்கிய அம்பிகை கௌமாரி அசுரர்களுடன் போரிட வந்தாள்.",
        '1.17': "அவ்வாறே விஷ்ணுவின் சக்தியான வைஷ்ணவி கருடன் மீது அமர்ந்து சங்கு, சக்கரம், கதை, சார்ங்க வில், வாள் ஏந்தி வந்தாள்.",
        '1.18': "ஒப்பற்ற யக்ஞ வராக வடிவம் தாங்கிய ஹரியின் சக்தியும் வராக உடலைத் தாங்கி அங்கே வந்தாள் (வாராஹீ).",
        '1.19': "நரசிம்மனைப் போன்ற உடலைத் தாங்கிய நாரஸிம்ஹீ, பிடரியின் அசைவால் விண்மீன் கூட்டங்களைச் சிதறடித்தவாறு அங்கே வந்தாள்.",
        '1.20': "அவ்வாறே ஐந்த்ரீ வஜ்ரத்தைக் கையில் ஏந்தி யானைகளின் அரசன் மீது அமர்ந்து ஆயிரம் கண்களுடன் வந்தாள்; சக்ரன் (இந்திரன்) எப்படியோ அவளும் அப்படியே.",
        '1.21': "அப்போது அந்தத் தேவசக்திகளால் சூழப்பட்ட ஈசானன் (சிவன்) சண்டிகையிடம் “என் மகிழ்ச்சிக்காக அசுரர்களை விரைவில் கொல்” என்றான்.",
        '1.22': "அப்போது தேவியின் உடலிலிருந்து மிகக் கொடிய, மிகக் கடுமையான, நூறு நரிகளைப் போல ஊளையிடும் சண்டிகா சக்தி வெளிப்பட்டாள்.",
        '1.23': "அந்த வெல்லற்கரியவள் புகை நிறச் சடையுடைய ஈசானனிடம் கூறினாள்: “பகவானே, நீ தூதனாகச் சும்ப நிசும்பரிடம் செல்.”",
        '1.24': "“மிகுந்த செருக்குடைய தானவர்களான சும்ப நிசும்பரிடமும், அங்கே போருக்குக் கூடியுள்ள மற்ற தானவர்களிடமும் இவ்வாறு சொல்:”",
        '1.25': "“இந்திரன் மூவுலகையும் பெறட்டும்; தேவர்கள் அவிர்பாகத்தை அனுபவிக்கட்டும். நீங்கள் வாழ விரும்பினால் பாதாளத்துக்குச் செல்லுங்கள்.”",
        '1.26': "“ஆனால் வலிமைச் செருக்கால் நீங்கள் போரை விரும்பினால் வாருங்கள்; என் நரிகள் உங்கள் சதையால் நிறைவுறட்டும்.”",
        '1.27': "அந்தத் தேவி சிவனையே தூதுப் பணிக்கு அமர்த்தியதால், இவ்வுலகில் அவள் ‘சிவதூதீ’ என்று புகழ்பெற்றாள்.",
        '1.28': "சர்வன் (சிவன்) தெரிவித்த தேவியின் சொற்களைக் கேட்டு அந்த மகாசுரர்கள் சினம் நிறைந்து காத்யாயனி இருந்த இடத்துக்குச் சென்றனர்.",
        '1.29': "அப்போது தொடக்கத்திலேயே பொங்கிய சினத்துடன் தேவர்களின் பகைவர்கள் அந்தத் தேவி மீது அம்புகள், சக்திகள், ருஷ்டிகள் ஆகியவற்றின் மழையைப் பொழிந்தனர்.",
        '1.30': "அவள் வளைத்த வில்லிலிருந்து விடுத்த பேரம்புகளால் அவர்கள் எறிந்த அம்புகள், சூலங்கள், சக்திகள், கோடரிகள் ஆகியவற்றை விளையாட்டாக வெட்டினாள்.",
        '1.31': "அவள் முன்னே காளி சூலத்தின் தாக்குதலால் பகைவர்களைப் பிளந்தும், கட்வாங்கத்தால் நசுக்கியும் திரிந்தாள்.",
        '1.32': "பிரம்மாணி எங்கெங்கு ஓடினாளோ அங்கெல்லாம் கமண்டல நீரைத் தெளித்துப் பகைவர்களை வீரமும் ஒளியும் இழந்தவர்களாக்கினாள்.",
        '1.33': "மாஹேச்வரி திரிசூலத்தாலும், வைஷ்ணவி சக்கரத்தாலும், பெருஞ்சினம் கொண்ட கௌமாரி வேலாலும் அசுரர்களைக் கொன்றனர்.",
        '1.34': "ஐந்த்ரீயின் வஜ்ராயுதத் தாக்குதலால் பிளக்கப்பட்ட நூற்றுக்கணக்கான தைத்ய தானவர்கள் குருதி வெள்ளத்தைப் பொழிந்தவாறு தரையில் வீழ்ந்தனர்.",
        '1.35': "வராக வடிவினளின் மூக்கின் தாக்குதலால் நொறுங்கியும், கோரைப் பற்களின் நுனியால் மார்பு கிழிந்தும், சக்கரத்தால் பிளக்கப்பட்டும் அவர்கள் வீழ்ந்தனர்.",
        '1.36': "நாரஸிம்ஹீ நகங்களால் கிழித்த மற்ற மகாசுரர்களை விழுங்கியவாறு, தன் முழக்கத்தால் திசைகளையும் வானையும் நிரப்பியவாறு போர்க்களத்தில் திரிந்தாள்.",
        '1.37': "சிவதூதீயின் கொடிய அட்டகாசச் சிரிப்பால் தாக்கப்பட்ட அசுரர்கள் தரையில் வீழ்ந்தனர்; வீழ்ந்த அவர்களை அவள் அப்போது விழுங்கினாள்.",
        '1.38': "இவ்வாறு சினமுற்ற மாத்ருகணம் பல வழிகளில் மகாசுரர்களை நசுக்குவதைக் கண்டு தேவர்களின் பகைவர் படைவீரர்கள் ஓடிப்போயினர்.",
        '1.39': "மாத்ருகணத்தால் துன்புறுத்தப்பட்டு ஓடும் அசுரர்களைக் கண்டு ரக்தபீஜன் என்னும் மகாசுரன் சினத்துடன் போரிட வந்தான்.",
        '1.40': "அவன் உடலிலிருந்து ஒரு துளி குருதி தரையில் விழும்போதெல்லாம், அவனுக்கு நிகரான அளவுடைய ஓர் அசுரன் பூமியிலிருந்து எழுந்தான்.",
        '1.41': "கதை ஏந்திய அந்த மகாசுரன் இந்திர சக்தியுடன் போரிட்டான்; அப்போது ஐந்த்ரீ தன் வஜ்ரத்தால் ரக்தபீஜனைத் தாக்கினாள்.",
        '1.42': "வஜ்ரத்தால் தாக்கப்பட்ட அவனிடமிருந்து விரைவில் மிகுந்த குருதி வழிந்தது; அதிலிருந்து அவனுடைய வடிவும் வீரமும் கொண்ட வீரர்கள் எழுந்தனர்.",
        '1.43': "அவன் உடலிலிருந்து எத்தனை குருதித் துளிகள் விழுந்தனவோ, அத்தனை ஆண்கள் அவனுடைய ஆற்றல், வலிமை, வீரத்துடன் பிறந்தனர்.",
        '1.44': "குருதியிலிருந்து பிறந்த அந்த ஆண்களும் அங்கே மாத்ருகைகளுடன் கொடிய ஆயுதங்களின் தாக்குதலுடன் மிகப் பயங்கரமான போர் புரிந்தனர்.",
        '1.45': "மீண்டும் வஜ்ரத் தாக்குதலால் அவன் தலை காயமடைந்தபோது குருதி பெருகியது; அதிலிருந்து ஆயிரக்கணக்கான ஆண்கள் பிறந்தனர்.",
        '1.46': "வைஷ்ணவி போரில் அவனைச் சக்கரத்தால் தாக்கினாள்; ஐந்த்ரீ அந்த அசுரர் தலைவனைக் கதையால் அடித்தாள்.",
        '1.47': "வைஷ்ணவியின் சக்கரத்தால் பிளக்கப்பட்ட அவன் குருதிப் பெருக்கிலிருந்து பிறந்த, அவனுக்கு நிகரான ஆயிரக்கணக்கான மகாசுரர்களால் உலகம் நிறைந்தது.",
        '1.48': "கௌமாரி வேலாலும், வாராஹீ வாளாலும், மாஹேச்வரி திரிசூலத்தாலும் மகாசுரன் ரக்தபீஜனைத் தாக்கினர்.",
        '1.49': "சினம் நிறைந்த மகா அசுரன் ரக்தபீஜனும் எல்லா மாத்ருகைகளையும் தனித்தனியே கதையால் தாக்கினான்.",
        '1.50': "சக்தி, சூலம் முதலியவற்றால் மீண்டும் மீண்டும் தாக்கப்பட்ட அவனிடமிருந்து தரையில் விழுந்த குருதிப் பெருக்கிலிருந்து நூற்றுக்கணக்கான அசுரர்கள் தோன்றினர்.",
        '1.51': "அசுரனின் குருதியிலிருந்து பிறந்த அந்த அசுரர்களால் உலகம் முழுதும் நிறைந்தது; அப்போது தேவர்கள் பெரும் அச்சம் அடைந்தனர்.",
        '1.52': "வருந்திய தேவர்களைக் கண்டு சண்டிகை சிரித்து விரைவாகக் காளியிடம் “சாமுண்டே, உன் வாயை அகலத் திற” என்றாள்.",
        '1.53': "“என் ஆயுதத் தாக்குதலால் விழும் குருதித் துளிகளையும், ரக்தபீஜனின் குருதித் துளிகளிலிருந்து பிறக்கும் மகாசுரர்களையும் உன் இந்த வேகமான வாயால் ஏந்திக்கொள்.”",
        '1.54': "“அவற்றிலிருந்து பிறக்கும் மகாசுரர்களை விழுங்கியவாறு போர்க்களத்தில் திரி. இவ்வாறு குருதி வற்றி இந்த அசுரன் அழிவான்.”",
        '1.55': "“நீ அந்தக் கொடியவர்களை விழுங்கினால் வேறு யாரும் தோன்ற மாட்டார்கள்.” என்று அவளிடம் கூறித் தேவி அவனைச் சூலத்தால் தாக்கினாள்.",
        '1.56': "காளி ரக்தபீஜனின் குருதியை வாயால் ஏந்தினாள். அப்போது அவன் அங்கே சண்டிகையைக் கதையால் தாக்கினான்.",
        '1.57': "ஆனால் அந்தக் கதைத் தாக்குதல் அவளுக்குச் சிறிதும் வலியை ஏற்படுத்தவில்லை. காயமுற்ற அவன் உடலிலிருந்து மிகுந்த குருதி வழிந்தது.",
        '1.58': "அது எங்கெங்கு வழிந்ததோ அங்கெல்லாம் சாமுண்டா தன் வாயால் அதை ஏந்தினாள்; குருதி விழுந்ததால் அவள் வாயிலேயே தோன்றிய மகாசுரர்களை —",
        '1.59': "— சாமுண்டா விழுங்கினாள்; அவன் குருதியையும் பருகினாள். தேவி சூலம், வஜ்ரம், அம்புகள், வாள்கள், ருஷ்டிகள் ஆகியவற்றால்,",
        '1.60': "சாமுண்டா குருதியைப் பருகிய அந்த ரக்தபீஜனைக் கொன்றாள். ஆயுதக் கூட்டத்தால் தாக்கப்பட்ட அவன் தரையில் வீழ்ந்தான் —",
        '1.61': "— அரசனே, மகாசுரன் ரக்தபீஜன் குருதியற்றவனாகி வீழ்ந்தான். அப்போது மன்னா, தேவர்கள் அளவற்ற மகிழ்ச்சி அடைந்தனர்.",
        '1.62': "தேவர்களிடமிருந்து தோன்றிய மாத்ருகணம் குருதி மயக்கத்தால் களிப்புற்று நடனமாடியது.",
        '1.63': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “ரக்தபீஜ வதம்” என்னும் எட்டாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'devi-mahatmyam-09': {
      verses: {
        '0.0': "ஓம். பந்தூக மலரைப் போலவும் பொன்னைப் போலவும் ஒளிர்வதும், தன் கரங்களில் அழகிய ஜபமாலை, பாசம், அங்குசம், வரமுத்திரை ஆகியவற்றைத் தாங்கியதும், பிறைச் சந்திரனை அணிகலனாகக் கொண்டதும், முக்கண்ணுடையதுமான அர்த்தநாரீச்வர வடிவை எப்போதும் சரணடைகிறேன்.",
        '1.0': "அரசன் கூறினான்:",
        '1.1': "“பகவானே, ரக்தபீஜ வதம் தொடர்பான தேவியின் சரித்திர மகிமையை நீங்கள் எனக்குக் கூறியது வியப்பானது.”",
        '1.2': "“ரக்தபீஜன் வீழ்ந்த பின் சும்பனும், மிகுந்த சினமுடைய நிசும்பனும் என்ன செய்தனர் என்பதை மேலும் கேட்க விரும்புகிறேன்.”",
        '1.3': "ரிஷி கூறினார்:",
        '1.4': "ரக்தபீஜன் வீழ்ந்து, போரில் மற்றவர்களும் கொல்லப்பட்டபோது சும்பாசுரனும் நிசும்பனும் அளவற்ற சினம் கொண்டனர்.",
        '1.5': "தன் பெரும் படை அழிக்கப்படுவதைக் கண்டு கொதிப்புடன் நிசும்பன் அசுரர்களின் முதன்மைப் படையுடன் முன்னே பாய்ந்தான்.",
        '1.6': "அவனுக்கு முன்னும் பின்னும் இரு பக்கங்களிலும் சினத்துடன் உதடுகளைக் கடித்தவாறு மகாசுரர்கள் தேவியைக் கொல்ல வந்தனர்.",
        '1.7': "பெரும் வீரனான சும்பனும் தன் படைகள் சூழ, மாத்ருகைகளுடன் போரிட்டு, சினத்துடன் சண்டிகையைக் கொல்ல வந்தான்.",
        '1.8': "அப்போது தேவிக்கும் சும்ப நிசும்பருக்கும் கடும் போர் நடந்தது; மழை பொழியும் இரு மேகங்களைப் போல அவர்கள் மிகக் கொடிய அம்பு மழையைப் பொழிந்தனர்.",
        '1.9': "அவ்விருவர் எய்த அம்புகளைச் சண்டிகை தன் அம்புக் கூட்டங்களால் வெட்டினாள்; ஆயுதக் கூட்டங்களால் அவ்விரு அசுரர் தலைவர்களின் அங்கங்களைத் தாக்கினாள்.",
        '1.10': "நிசும்பன் கூரிய வாளையும் ஒளிரும் கேடயத்தையும் எடுத்துத் தேவியின் சிறந்த வாகனமான சிங்கத்தின் தலையில் தாக்கினான்.",
        '1.11': "வாகனம் தாக்கப்பட்டதும் தேவி கத்திமுனை அம்பால் நிசும்பனின் சிறந்த வாளையும், எட்டுச் சந்திரக் குறிகளுடைய கேடயத்தையும் விரைவில் வெட்டினாள்.",
        '1.12': "கேடயமும் வாளும் வெட்டப்பட்டதும் அந்த அசுரன் சக்தி ஆயுதத்தை எறிந்தான்; எதிரே வந்த அதையும் அவள் சக்கரத்தால் இரண்டாகப் பிளந்தாள்.",
        '1.13': "அப்போது சினத்தால் பொங்கிய தானவன் நிசும்பன் சூலத்தை எடுத்தான்; வந்த அதையும் தேவி முஷ்டியின் அடியால் தூளாக்கினாள்.",
        '1.14': "அப்போது அவன் கதையைச் சுழற்றிச் சண்டிகையை நோக்கி எறிந்தான்; தேவியின் திரிசூலத்தால் பிளக்கப்பட்ட அதுவும் சாம்பலானது.",
        '1.15': "அப்போது கோடரியுடன் வந்த அந்த அசுரர்களில் சிறந்தவனைத் தேவி அம்புக் கூட்டங்களால் தாக்கித் தரையில் வீழ்த்தினாள்.",
        '1.16': "அச்சந்தரும் வீரமுடைய தன் தம்பி நிசும்பன் தரையில் வீழ்ந்ததும் சும்பன் பெருஞ்சினத்துடன் அம்பிகையைக் கொல்லப் புறப்பட்டான்.",
        '1.17': "தேரில் நின்று, ஒப்பற்ற எட்டுக் கைகளில் சிறந்த ஆயுதங்களை உயர்த்திப் பிடித்து, அவன் வானம் முழுவதையும் நிறைத்து ஒளிர்ந்தான்.",
        '1.18': "அவன் வருவதைக் கண்டு தேவி சங்கை ஊதினாள்; வில்நாணின் தாங்க முடியாத ஓசையையும் எழுப்பினாள்.",
        '1.19': "எல்லா அசுரப் படைகளின் ஒளியையும் அழிக்கும் தன் மணியோசையால் அவள் திசைகளை நிரப்பினாள்.",
        '1.20': "அப்போது சிங்கம் பெரும் யானைகளின் மதத்தைப் போக்கும் பெரும் முழக்கங்களால் வானையும் பூமியையும் பத்துத் திசைகளையும் நிரப்பியது.",
        '1.21': "அப்போது காளி வானில் எழும்பி இரு கைகளாலும் பூமியை அறைந்தாள்; அந்த ஒலியால் முந்தைய ஒலிகள் அனைத்தும் அமிழ்ந்தன.",
        '1.22': "சிவதூதீ அமங்கலமான அட்டகாசச் சிரிப்பை எழுப்பினாள்; அந்த ஒலிகளால் அசுரர்கள் நடுங்கினர், சும்பன் பெருஞ்சினம் அடைந்தான்.",
        '1.23': "அம்பிகை “தீயவனே, நில், நில்!” என்றபோது வானில் நின்ற தேவர்கள் “ஜயம்!” என்று முழங்கினர்.",
        '1.24': "சும்பன் வந்து எறிந்த, தீச்சுடர்களால் மிகக் கொடிய, நெருப்புக் குவியல் போல் வந்த சக்தி ஆயுதத்தைத் தேவி பெரும் எரிகொள்ளியால் தடுத்தாள்.",
        '1.25': "அரசனே, சும்பனின் சிம்மநாதம் மூவுலகின் இடைவெளியை நிரப்பியது; ஆனால் (தேவியின்) இடிபோன்ற கொடிய ஒலி அதை வென்றது.",
        '1.26': "சும்பன் எய்த அம்புகளைத் தேவியும், அவள் எய்த அம்புகளைச் சும்பனும் தத்தம் கொடிய அம்புகளால் நூறு நூறாக, ஆயிரம் ஆயிரமாக வெட்டினர்.",
        '1.27': "அப்போது சினமுற்ற சண்டிகை அவனைச் சூலத்தால் தாக்கினாள்; தாக்கப்பட்ட அவன் மயங்கித் தரையில் வீழ்ந்தான்.",
        '1.28': "அப்போது நிசும்பன் நினைவு மீண்டு வில்லை எடுத்துத் தேவியையும் காளியையும் சிங்கத்தையும் அம்புகளால் தாக்கினான்.",
        '1.29': "மீண்டும் தானவர் தலைவனான அந்தத் திதியின் மகன் பத்தாயிரம் கைகளை உண்டாக்கிக்கொண்டு சக்கரங்களால் சண்டிகையை மூடினான்.",
        '1.30': "அப்போது துன்பத்தையும் துயரத்தையும் அழிக்கும் பகவதி துர்கை சினமுற்று அந்தச் சக்கரங்களையும் அம்புகளையும் தன் அம்புகளால் வெட்டினாள்.",
        '1.31': "அப்போது நிசும்பன் கதையை எடுத்துக்கொண்டு அசுரப் படை சூழச் சண்டிகையைக் கொல்ல வேகமாகப் பாய்ந்தான்.",
        '1.32': "அவன் பாய்ந்து வரும்போதே சண்டிகை கூரிய முனையுடைய வாளால் அவன் கதையை விரைவில் வெட்டினாள்; அவன் சூலத்தை எடுத்தான்.",
        '1.33': "சூலத்துடன் வந்த, தேவர்களைத் துன்புறுத்திய நிசும்பனின் இதயத்தைச் சண்டிகை வேகமாக எறிந்த சூலத்தால் துளைத்தாள்.",
        '1.34': "சூலத்தால் பிளக்கப்பட்ட அவன் இதயத்திலிருந்து பெரும் வலிமையும் பெரும் வீரமும் உடைய இன்னொரு மனிதன் “நில்!” என்று கூவியவாறு வெளிப்பட்டான்.",
        '1.35': "அவன் வெளிப்படும்போதே தேவி உரக்கச் சிரித்து வாளால் அவன் தலையை வெட்டினாள்; அப்போது அவன் தரையில் வீழ்ந்தான்.",
        '1.36': "அப்போது சிங்கம் கோரைப் பற்களால் கழுத்துகளை நசுக்கிய கொடிய அசுரர்களை விழுங்கியது; காளியும் சிவதூதீயும் மற்றவர்களை விழுங்கினர்.",
        '1.37': "சில மகாசுரர்கள் கௌமாரியின் வேலால் பிளக்கப்பட்டு அழிந்தனர்; மற்றவர்கள் பிரம்மாணியின் மந்திரத்தால் தூய்மையான நீரால் விரட்டப்பட்டனர்.",
        '1.38': "மேலும் சிலர் மாஹேச்வரியின் திரிசூலத்தால் பிளக்கப்பட்டு வீழ்ந்தனர்; சிலர் வாராஹீயின் மூக்குத் தாக்குதலால் தரையில் தூளாயினர்.",
        '1.39': "வைஷ்ணவியின் சக்கரத்தால் தானவர்கள் துண்டு துண்டாக்கப்பட்டனர்; மற்றவர்கள் ஐந்த்ரீயின் கை நுனியிலிருந்து விடுபட்ட வஜ்ரத்தால்.",
        '1.40': "சில அசுரர்கள் அழிந்தனர், சிலர் பெரும் போரிலிருந்து ஓடினர், மற்றவர்கள் காளி, சிவதூதீ, சிங்கம் ஆகியோரால் விழுங்கப்பட்டனர்.",
        '1.41': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “நிசும்ப வதம்” என்னும் ஒன்பதாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'devi-mahatmyam-10': {
      verses: {
        '0.0': "ஓம். உருக்கிய பொன் போல் அழகியவளும், சூரியன், சந்திரன், அக்னி ஆகியோரைக் கண்களாகக் கொண்டவளும், அழகிய கரங்களில் வில், அம்பு, அங்குசம், பாசம், சூலம் ஏந்தியவளும், சிவசக்தி வடிவினளும், பிறைச் சந்திரனை அணிந்தவளுமான காமேச்வரியை இதயத்தில் வழிபடுகிறேன்.",
        '1.0': "ரிஷி கூறினார்:",
        '1.1': "தன் உயிருக்கு நிகரான தம்பி நிசும்பன் கொல்லப்பட்டதையும், படை அழிக்கப்படுவதையும் கண்டு சும்பன் சினத்துடன் கூறினான்:",
        '1.2': "“கொடியவளே துர்கே, வலிமைச் செருக்கால் இறுமாப்புக் கொள்ளாதே. மிகுந்த அகந்தையுடைய நீ பிறரின் வலிமையைச் சார்ந்தே போரிடுகிறாய்.”",
        '1.3': "தேவி கூறினாள்:",
        '1.4': "“இவ்வுலகில் நான் ஒருத்தியே இருக்கிறேன்; என்னைத் தவிர இரண்டாமவள் யார்? கொடியவனே, என் விபூதிகளான இவர்கள் என்னுள்ளேயே புகுவதைப் பார்.”",
        '1.5': "அப்போது பிரம்மாணி முதலிய அந்தத் தேவியர் அனைவரும் அந்தத் தேவியின் உடலில் ஒடுங்கினர்; அம்பிகை ஒருத்தியே எஞ்சினாள்.",
        '1.6': "தேவி கூறினாள்:",
        '1.7': "“என் ஆற்றலால் நான் இங்கே கொண்டிருந்த பல வடிவங்களை உள்ளிழுத்துக்கொண்டேன்; இப்போது நான் ஒருத்தியே போரில் நிற்கிறேன். உறுதியாக நில்!”",
        '1.8': "ரிஷி கூறினார்:",
        '1.9': "அப்போது எல்லாத் தேவர்களும் அசுரர்களும் பார்த்துக்கொண்டிருக்கத் தேவிக்கும் சும்பனுக்கும் இடையே கொடிய போர் தொடங்கியது.",
        '1.10': "அம்பு மழைகளாலும், கூரிய ஆயுதங்களாலும், கொடிய அஸ்திரங்களாலும் அவர்களின் போர் மீண்டும் எல்லா உலகங்களையும் அஞ்சவைப்பதாயிற்று.",
        '1.11': "அம்பிகை விடுத்த நூற்றுக்கணக்கான திவ்ய அஸ்திரங்களை அசுர அரசன் அவற்றை எதிர்க்கும் அஸ்திரங்களால் முறியடித்தான்.",
        '1.12': "அவன் விடுத்த திவ்ய அஸ்திரங்களைப் பரமேச்வரி கடுமையான ‘ஹும்’ முதலிய ஒலிகளால் விளையாட்டாக முறியடித்தாள்.",
        '1.13': "அப்போது அந்த அசுரன் நூற்றுக்கணக்கான அம்புகளால் தேவியை மூடினான்; சினமுற்ற தேவி அம்புகளால் அவன் வில்லை வெட்டினாள்.",
        '1.14': "வில் வெட்டப்பட்டதும் அசுர அரசன் சக்தி ஆயுதத்தை எடுத்தான்; அவன் கையில் இருந்த அதையும் தேவி சக்கரத்தால் வெட்டினாள்.",
        '1.15': "அப்போது அசுரத் தலைவர்களின் தலைவன் ஒளிரும் வாளையும், நூறு சந்திரக் குறிகளுடைய பிரகாசமான கேடயத்தையும் எடுத்துத் தேவியை நோக்கிப் பாய்ந்தான்.",
        '1.16': "அவன் பாய்ந்து வரும்போதே சண்டிகை வில்லிலிருந்து எய்த கூரிய அம்புகளால் அவன் வாளையும், சூரியக் கதிர் போன்று தெளிவான கேடயத்தையும் விரைவில் வெட்டினாள்.",
        '1.17': "(அவள் அவன் குதிரைகளையும், சாரதியுடன் தேரையும் வீழ்த்தினாள்.) குதிரைகள் கொல்லப்பட்டு, வில் முறிந்து, சாரதியற்ற அந்த அசுரன் அம்பிகையைக் கொல்ல முனைந்து கொடிய முத்கரத்தை எடுத்தான்.",
        '1.18': "அவன் பாய்ந்து வருகையில் அவள் கூரிய அம்புகளால் அவன் முத்கரத்தை வெட்டினாள்; இருந்தும் அவன் முஷ்டியை உயர்த்தி வேகமாக அவளை நோக்கிப் பாய்ந்தான்.",
        '1.19': "அந்த அசுரர்களில் சிறந்தவன் தேவியின் மார்பில் முஷ்டியால் குத்தினான்; தேவியும் அவன் மார்பில் உள்ளங்கையால் அறைந்தாள்.",
        '1.20': "உள்ளங்கை அடியால் தாக்கப்பட்ட அந்த அசுர அரசன் தரையில் விழுந்தான்; ஆனால் உடனே மீண்டும் எழுந்தான்.",
        '1.21': "அவன் எழும்பித் தேவியைப் பற்றிக்கொண்டு உயர வானில் சென்றான்; அங்கேயும் எந்த ஆதாரமுமின்றிச் சண்டிகை அவனுடன் போரிட்டாள்.",
        '1.22': "அப்போது வானில் அசுரனும் சண்டிகையும் ஒருவரோடொருவர் மல்யுத்தம் செய்தனர்; முன்னெப்போதும் நிகழாத அது சித்தர்களையும் முனிவர்களையும் வியப்பில் ஆழ்த்தியது.",
        '1.23': "அவனுடன் நீண்ட நேரம் மல்யுத்தம் செய்த பின் அம்பிகை அவனைத் தூக்கிச் சுழற்றித் தரையில் வீசினாள்.",
        '1.24': "வீசப்பட்ட அந்தத் தீயவன் தரையை அடைந்து, முஷ்டியை உயர்த்திச் சண்டிகையைக் கொல்லும் விருப்பத்துடன் வேகமாகப் பாய்ந்தான்.",
        '1.25': "அவ்வாறு வந்த எல்லா அசுரர்களின் தலைவனைத் தேவி சூலத்தால் மார்பைப் பிளந்து பூமியில் வீழ்த்தினாள்.",
        '1.26': "தேவியின் சூல நுனியால் காயமுற்ற அவன் உயிரிழந்து, கடல்கள், தீவுகள், மலைகளுடன் கூடிய பூமி முழுவதையும் நடுங்கச் செய்தவாறு தரையில் வீழ்ந்தான்.",
        '1.27': "அந்தத் தீயவன் கொல்லப்பட்டதும் உலகம் முழுதும் தெளிவுற்றது; உலகம் முழு நலம் பெற்றது, வானம் தூய்மையானது.",
        '1.28': "முன்பு தோன்றிய எரிநட்சத்திரங்களுடன் கூடிய தீய சகுன மேகங்கள் அடங்கின; அவன் வீழ்ந்ததும் ஆறுகள் தத்தம் வழியிலேயே ஓடலாயின.",
        '1.29': "அவன் கொல்லப்பட்டதும் எல்லாத் தேவகணங்களின் மனமும் மகிழ்ச்சியால் நிறைந்தது; கந்தர்வர்கள் இனிமையாகப் பாடினர்.",
        '1.30': "மற்றவர்கள் இசைக்கருவிகளை இசைத்தனர், அப்ஸரஸ் கூட்டங்கள் நடனமாடின; புனிதமான காற்று வீசியது, சூரியன் நன்கு ஒளிர்ந்தான்.",
        '1.31': "அணைந்திருந்த வேள்வித் தீகள் மீண்டும் சுடர்விட்டன; திசைகளில் எழுந்த அச்சந்தரும் ஒலிகள் அடங்கின.",
        '1.32': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “சும்ப வதம்” என்னும் பத்தாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'devi-mahatmyam-11': {
      verses: {
        '0.0': "ஓம். உதய சூரியனைப் போல் ஒளிர்பவளும், சந்திரனை மகுடமாகக் கொண்டவளும், உயர்ந்த தனங்களும் மூன்று கண்களும் உடையவளும், புன்னகை முகத்தினளும், வரம், அங்குசம், பாசம், அபயம் ஆகியவற்றைக் கைகளில் காட்டுபவளுமான புவனேச்வரியை வழிபடுகிறேன்.",
        '1.0': "ரிஷி கூறினார்:",
        '3.0': "தேவி கூறினாள்:",
        '3.1': "“தேவகணங்களே, நான் வரம் அருள்பவள். உலகங்களுக்கு நன்மை தரும் எந்த வரத்தை நீங்கள் மனத்தில் விரும்புகிறீர்களோ அதைக் கேளுங்கள்; நான் அருள்கிறேன்.”",
        '3.2': "தேவர்கள் கூறினர்:",
        '3.3': "“அனைத்துக்கும் ஈச்வரியே, இவ்வாறே நீ மூவுலகின் எல்லாத் துன்பங்களையும் தணிப்பாயாக; எங்கள் பகைவர்களை அழிப்பாயாக.”",
        '3.4': "தேவி கூறினாள்:",
        '3.5': "“வைவஸ்வத மன்வந்தரத்தின் இருபத்தெட்டாவது யுகத்தில் சும்பன், நிசும்பன் என்னும் வேறு இரு மகாசுரர்கள் பிறப்பார்கள்.”",
        '3.6': "“அப்போது நந்தகோபனின் இல்லத்தில் யசோதையின் கருவில் பிறந்து, விந்திய மலையில் வசித்து, அவ்விருவரையும் அழிப்பேன்.”",
        '3.7': "“மீண்டும் மிகக் கடுமையான வடிவில் பூமியில் அவதரித்து விப்ரசித்தியின் வம்சத்துத் தானவர்களைக் கொல்வேன்.”",
        '3.8': "“விப்ரசித்தி வம்சத்து அந்தக் கொடிய மகாசுரர்களை நான் விழுங்கும்போது என் பற்கள் மாதுளம்பூவைப் போலச் சிவக்கும்.”",
        '3.9': "“ஆகவே விண்ணுலகில் தேவர்களும் மண்ணுலகில் மனிதர்களும் என்னைத் துதித்து எப்போதும் ‘ரக்ததந்திகா’ (சிவந்த பல்லுடையவள்) என்று அழைப்பார்கள்.”",
        '3.10': "“மீண்டும் நூறு ஆண்டுகள் மழையின்றி நீரின்றி இருக்கும்போது முனிவர்களால் துதிக்கப்பட்டு, கருவில் பிறவாதவளாக நான் பூமியில் தோன்றுவேன்.”",
        '3.11': "“அப்போது நான் நூறு கண்களால் முனிவர்களை நோக்குவதால் மனிதர்கள் என்னை ‘சதாக்ஷீ’ (நூறு கண்ணுடையவள்) என்று போற்றுவார்கள்.”",
        '3.12': "“தேவர்களே, அப்போது மழை வரும்வரை என் உடலிலிருந்தே தோன்றிய, உயிரைக் காக்கும் கீரை காய்கறிகளால் (சாகங்களால்) உலகம் முழுவதையும் காப்பேன்.”",
        '3.13': "“அப்போது நான் பூமியில் ‘சாகம்பரீ’ என்று புகழ்பெறுவேன்; அதே காலத்தில் துர்கமன் என்னும் மகாசுரனைக் கொல்வேன்.”",
        '3.14': "“அதனால் என் பெயர் ‘துர்கா தேவீ’ என்று புகழ்பெறும். மீண்டும் நான் இமயத்தில் கொடிய வடிவம் தாங்கி —”",
        '3.15': "“— முனிவர்களைக் காப்பதற்காக ராக்ஷஸர்களை விழுங்கும்போது, எல்லா முனிவர்களும் பணிந்து என்னைத் துதிப்பார்கள்.”",
        '3.16': "“அப்போது என் பெயர் ‘பீமா தேவீ’ என்று புகழ்பெறும். அருணன் என்னும் அசுரன் மூவுலகிலும் பெரும் துன்பம் விளைவிக்கும்போது —”",
        '3.17': "“— அப்போது நான் எண்ணற்ற வண்டுகளாலான ப்ரமர வடிவம் தாங்கி மூவுலகின் நன்மைக்காக அந்த மகாசுரனைக் கொல்வேன்.”",
        '3.18': "“அப்போது மக்கள் எங்கும் என்னை ‘ப்ராமரீ’ என்று துதிப்பார்கள். இவ்வாறு எப்போதெல்லாம் தானவர்களால் துன்பம் எழுகிறதோ —”",
        '3.19': "“— அப்போதெல்லாம் நான் அவதரித்துப் பகைவர்களை அழிப்பேன்.”",
        '3.20': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “தேவீ ஸ்துதி” என்னும் பதினொன்றாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'devi-mahatmyam-12': {
      verses: {
        '0.0': "ஓம். மின்னல் மாலை போல் ஒளிர்பவளும், சிங்கத்தின் தோளில் அமர்ந்தவளும், அச்சமூட்டுபவளும், வாளும் கேடயமும் ஏந்திய கன்னியரால் சேவிக்கப்படுபவளும், கைகளில் சக்கரம், கதை, வாள், கேடயம், அம்புகள், வில், பாசம், தர்ஜனீ முத்திரை ஆகியவற்றைத் தாங்கியவளும், அக்னி வடிவினளும், சந்திரனை அணிந்தவளுமான முக்கண் துர்கையை வழிபடுகிறேன்.",
        '1.0': "தேவி கூறினாள்:",
        '1.1': "“எவர் ஒருமுகப்பட்ட மனத்துடன் இந்தத் துதிகளால் நாள்தோறும் என்னைத் துதிக்கிறாரோ, அவருடைய எல்லாத் துன்பங்களையும் ஐயமின்றி அழிப்பேன்.”",
        '1.2': "“மது கைடபரின் அழிவையும், மகிஷாசுர வதத்தையும், அவ்வாறே சும்ப நிசும்ப வதத்தையும் எவர் போற்றிச் சொல்வார்களோ —”",
        '1.3': "“— அஷ்டமி, சதுர்தசி, நவமி திதிகளில் ஒருமுக மனத்துடன் பக்தியோடு என் இந்த உயர்ந்த மாஹாத்ம்யத்தை எவர் கேட்பார்களோ —”",
        '1.4': "“— அவர்களுக்கு எந்தப் பாவமும் நேராது, பாவத்தால் விளையும் ஆபத்துகளும் வராது; வறுமையும் அன்பர்களைப் பிரிதலும் ஏற்படாது.”",
        '1.5': "“அவருக்குப் பகைவர், கள்வர், அரசன் ஆகியோரிடமிருந்தோ, ஆயுதம், நெருப்பு, வெள்ளம் ஆகியவற்றிடமிருந்தோ ஒருபோதும் அச்சம் ஏற்படாது.”",
        '1.6': "“ஆகவே என் இந்த மாஹாத்ம்யத்தை ஒருமுகத்துடன் படிக்க வேண்டும், எப்போதும் பக்தியுடன் கேட்க வேண்டும்; ஏனெனில் அது மேலான மங்கள வழி.”",
        '1.7': "“என் இந்த மாஹாத்ம்யம் கொள்ளைநோயால் விளையும் எல்லாத் துன்பங்களையும், மூவகைத் தீய சகுனங்களையும் தணிக்கும்.”",
        '1.8': "“என் எந்த ஆலயத்தில் இது நாள்தோறும் முறையாகப் படிக்கப்படுகிறதோ அதை நான் ஒருபோதும் விடமாட்டேன்; அங்கே என் ஸாந்நித்யம் நிலைத்திருக்கும்.”",
        '1.9': "“பலி அர்ப்பணத்திலும், பூஜையிலும், அக்னி கார்யத்திலும், பெருவிழாவிலும் என் இந்தச் சரித்திரம் முழுவதையும் ஓத வேண்டும், கேட்கச் செய்ய வேண்டும்.”",
        '1.10': "“முறை அறிந்தவரோ அறியாதவரோ, இவ்வாறு செய்யப்பட்ட பலியையும் பூஜையையும் அக்னி ஹோமத்தையும் நான் மகிழ்வுடன் ஏற்பேன்.”",
        '1.11': "“சரத்காலத்தில் செய்யப்படும் ஆண்டு மகாபூஜையில் என் இந்த மாஹாத்ம்யத்தைப் பக்தியுடன் கேட்கும் —”",
        '1.12': "“— மனிதர் என் அருளால் எல்லாத் துன்பங்களிலிருந்தும் விடுபட்டுச் செல்வம், தானியம், மக்கள் ஆகியோருடன் கூடியவராவார்; இதில் ஐயமில்லை.”",
        '1.13': "“என் இந்த மாஹாத்ம்யத்தையும், மங்களமான என் அவதாரங்களையும், போர்களில் என் வீரத்தையும் கேட்டு மனிதன் அச்சமற்றவனாகிறான்.”",
        '1.14': "“என் மாஹாத்ம்யத்தைக் கேட்பவர்களின் பகைவர் அழிவர், நலம் உண்டாகும், அவர்கள் குலம் மகிழ்ந்திருக்கும்.”",
        '1.15': "“எல்லாச் சாந்தி கர்மங்களிலும், தீய கனவு கண்டபோதும், கொடிய கிரக தோஷங்களிலும் என் மாஹாத்ம்யத்தைக் கேட்க வேண்டும்.”",
        '1.16': "“துன்பங்களும் கொடிய கிரக தோஷங்களும் தணியும்; மனிதர்கள் கண்ட தீய கனவு நல்ல கனவாக மாறும்.”",
        '1.17': "“பாலகிரகங்களால் பீடிக்கப்பட்ட குழந்தைகளுக்கு இது அமைதி தரும்; மனிதர்களிடையே பிளவு ஏற்படும்போது நட்பை உண்டாக்கும் சிறந்த வழி இது.”",
        '1.18': "“இது எல்லாத் தீயோரின் வலிமையையும் அழிக்கும் மேலான வழி; இதை ஓதுவதாலேயே ராக்ஷஸர், பூதங்கள், பிசாசங்கள் அழியும்.”",
        '1.19': "“என் இந்த மாஹாத்ம்யம் முழுதும் என் ஸாந்நித்யத்தை உண்டாக்கும். பசு (பலி), மலர், அர்க்யம், தூபம், சிறந்த சந்தனம், தீபம் ஆகியவற்றாலும் —”",
        '1.20': "“— அந்தணர்க்கு உணவளித்தல், ஹோமங்கள், இரவும் பகலும் புனித நீர் தெளித்தல், மற்றும் பலவகை இன்பப் பொருள்கள், தானங்கள் ஆகியவற்றால் ஓராண்டில் எந்த —”",
        '1.21': "“— மகிழ்ச்சி எனக்கு ஏற்படுகிறதோ, அது இந்தப் புனிதச் சரித்திரத்தை ஒருமுறை கேட்பதாலேயே ஏற்படுகிறது. கேட்கப்பட்டால் இது பாவங்களைப் போக்கி ஆரோக்கியம் அருள்கிறது.”",
        '1.22': "“என் அவதாரங்களைப் போற்றுதல் தீய ஆவிகளிடமிருந்து காக்கும். தீய அசுரர்களை அழித்த போர்களில் என் சரித்திரத்தை —”",
        '1.23': "“— கேட்டால் மனிதர்களுக்குப் பகைவர்களால் அச்சம் ஏற்படாது. நீங்கள் செய்த துதிகளும், பிரம்மரிஷிகள் செய்த துதிகளும் —”",
        '1.24': "“— பிரம்மா செய்த துதிகளும் நல்ல புத்தியை அருள்கின்றன. காட்டிலோ, ஆளற்ற வழியிலோ காட்டுத்தீயால் சூழப்பட்டவனும் —”",
        '1.25': "“— ஆளற்ற இடத்தில் கள்வர்களால் சூழப்பட்டவனும், பகைவர்களால் பிடிக்கப்பட்டவனும், சிங்கம் புலிகளால் துரத்தப்பட்டவனும், காட்டில் காட்டு யானைகளால் துரத்தப்பட்டவனும் —”",
        '1.26': "“— சினமுற்ற அரசனால் கொல்லப்படக் கட்டளையிடப்பட்டவனும், சிறையில் கட்டுண்டவனும், பெருங்கடலில் கப்பலில் இருந்து காற்றால் அலைக்கழிக்கப்படுபவனும் —”",
        '1.27': "“— மிகக் கொடிய போரில் ஆயுதங்கள் விழும்போதும், எல்லாக் கொடிய துன்பங்களிலும், வேதனையால் வாடும்போதும் —”",
        '1.28': "“— என் இந்தச் சரித்திரத்தை நினைக்கும் மனிதன் இடரிலிருந்து விடுபடுவான். என் ஆற்றலால் சிங்கம் முதலியவையும், கள்வரும், பகைவரும் —”",
        '1.29': "“— என் சரித்திரத்தை நினைப்பவனிடமிருந்து தொலைவிலேயே ஓடிவிடுவர்.”",
        '1.30': "ரிஷி கூறினார்:",
        '1.31': "இவ்வாறு கூறிக் கடும் வீரமுடைய பகவதி சண்டிகை —",
        '1.32': "— தேவர்கள் பார்த்துக்கொண்டிருக்கையிலேயே அங்கேயே மறைந்தாள். அந்தத் தேவர்களும் அச்சம் நீங்கி முன்போலவே தத்தம் அதிகாரங்களை —",
        '1.33': "— பகைவர் கொல்லப்பட்டதால் யக்ஞ பாகங்களை அனுபவித்தவாறு ஏற்றனர். தேவர்களின் பகைவனான சும்பன் போரில் தேவியால் கொல்லப்பட்டதும் அசுரர்கள் —",
        '1.34': "— உலகை அழித்த மிகக் கொடியவனும் ஒப்பற்ற வீரனுமான அவனும், பெரும் வீரனான நிசும்பனும் கொல்லப்பட்டபோது, எஞ்சிய அசுரர்கள் பாதாளத்துக்குச் சென்றனர்.",
        '1.35': "அரசனே, இவ்வாறு அந்தப் பகவதி தேவி நித்யமானவளாயினும் மீண்டும் மீண்டும் தோன்றி உலகைக் காக்கிறாள்.",
        '1.36': "அவளாலேயே இந்த உலகம் மயங்குகிறது; அவளே உலகைப் பிறப்பிக்கிறாள். வேண்டும்போது அவள் ஞானத்தையும், மகிழும்போது வளத்தையும் அருள்கிறாள்.",
        '1.37': "மனிதர்களின் தலைவனே, மகாப்பிரளய காலத்தில் மகாமாரீ வடிவு கொள்ளும் அந்த மகாகாளியால் இந்தப் பிரபஞ்சம் முழுதும் நிறைந்துள்ளது.",
        '1.38': "உரிய காலத்தில் அவளே மகாமாரீ; பிறப்பற்ற அவளே படைப்பாகிறாள்; என்றுமுள்ள அவளே காலத்தில் உயிர்களைக் காக்கிறாள்.",
        '1.39': "வளமான காலத்தில் அவளே மனிதர்களின் இல்லங்களில் பெருக்கம் தரும் லக்ஷ்மி; இல்லாமைக் காலத்தில் அவளே அழிவுக்காக அலக்ஷ்மியாகிறாள்.",
        '1.40': "மலர், தூபம், சந்தனம் முதலியவற்றால் துதித்து வழிபடப்பட்ட அவள் செல்வத்தையும், மக்களையும், அறத்தில் நாட்டமுள்ள மனத்தையும், நற்கதியையும் அருள்கிறாள்.",
        '1.41': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “பலஸ்துதி” என்னும் பன்னிரண்டாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
    'devi-mahatmyam-13': {
      verses: {
        '0.0': "ஓம். உதய சூரிய மண்டலம் போல் ஒளிர்பவளும், நான்கு கைகளும் மூன்று கண்களும் உடையவளும், பாசம், அங்குசம், வரம், அபயம் ஆகியவற்றைத் தாங்கியவளுமான சிவையை வழிபடுகிறேன்.",
        '1.0': "ரிஷி கூறினார்:",
        '1.1': "“அரசனே, இவ்வாறு தேவியின் இந்த உயர்ந்த மாஹாத்ம்யத்தை உனக்குக் கூறினேன். இந்த உலகைத் தாங்கும் அந்தத் தேவி இத்தகைய ஆற்றல் உடையவள்.”",
        '1.2': "“பகவதி விஷ்ணுமாயையாலேயே ஞானமும் அருளப்படுகிறது. அவளாலேயே நீயும் இந்த வணிகனும் மற்ற விவேகிகளும் —”",
        '1.3': "“— மயங்குகிறீர்கள், மயங்கியுள்ளீர்கள், இனியும் மற்றவர்கள் மயங்குவார்கள். மகாராஜா, அந்தப் பரமேச்வரியைச் சரணடை.”",
        '1.4': "“வழிபடப்பட்டால் அவளே மனிதர்களுக்கு இன்பத்தையும் சுவர்க்கத்தையும் முக்தியையும் அருள்கிறாள்.”",
        '1.5': "மார்க்கண்டேயர் கூறினார்:",
        '1.6': "முனிவரின் இச்சொற்களைக் கேட்டு அரசன் ஸுரதன் —",
        '1.7': "— கடும் விரதங்களுடைய அந்த மகாபாக்யசாலியான ரிஷியை வணங்கி, அளவற்ற பற்றாலும் அரசு பறிக்கப்பட்டதாலும் மனம் வெறுத்து,",
        '1.8': "மாமுனிவரே, உடனே தவம் செய்யப் புறப்பட்டான்; அந்த வணிகனும் அன்னையின் தரிசனத்துக்காக நதிக்கரை மணல்திட்டில் தங்கினான்.",
        '1.9': "அந்த வணிகன் மேலான தேவீ ஸூக்தத்தை ஜபித்தவாறு தவம் செய்தான். அவ்விருவரும் அந்த மணல்திட்டில் தேவியின் மண் விக்ரகத்தை அமைத்து —",
        '1.10': "— மலர், தூபம், அக்னி, தர்ப்பணம் ஆகியவற்றால் அவளை வழிபட்டனர்; சில வேளை உண்ணாமலும், சில வேளை அளவோடு உண்டும், அவளிடமே மனத்தைச் செலுத்தி ஒருமுகப்பட்டிருந்தனர்.",
        '1.11': "தம் உடலின் குருதியால் நனைத்த பலியையும் அர்ப்பணித்தனர். இவ்வாறு தன்னடக்கமுள்ள அவ்விருவரும் மூன்று ஆண்டுகள் வழிபட்டபோது —",
        '1.12': "— உலகைத் தாங்கும் சண்டிகை மகிழ்ந்து நேரில் தோன்றிக் கூறினாள்.",
        '1.13': "தேவி கூறினாள்:",
        '1.14': "“அரசனே, குலத்தை மகிழ்விப்பவனே, நீங்கள் வேண்டுவது அனைத்தையும் என்னிடமிருந்து பெறுங்கள்; மகிழ்ந்த நான் அதை அருள்கிறேன்.”",
        '1.15': "மார்க்கண்டேயர் கூறினார்:",
        '1.16': "அப்போது அரசன் மறுபிறவியில் ஒருபோதும் அழியாத அரசையும், இப்பிறவியிலேயே பகைவர் படையை வலிமையால் அழித்துத் தன் சொந்த அரசையும் வரமாகக் கேட்டான்.",
        '1.17': "அந்த வணிகனும் உலகப் பற்றற்ற மனமுடைய அறிவாளியாக, ‘என்னுடையது’, ‘நான்’ என்னும் பற்றை நீக்கும் ஞானத்தை வேண்டினான்.",
        '1.18': "தேவி கூறினாள்:",
        '1.19': "“அரசனே, சில நாள்களிலேயே நீ உன் அரசைப் பெறுவாய்.”",
        '1.20': "“பகைவரைக் கொன்று அங்கே உன் அரசு அசையாது நிலைக்கும்.”",
        '1.21': "“இறந்த பின் மீண்டும் விவஸ்வான் (சூரிய) தேவனிடமிருந்து பிறப்பைப் பெற்று,”",
        '1.22': "“நீ பூமியில் ஸாவர்ணிகன் என்னும் மனுவாவாய்.”",
        '1.23': "“வணிகர்களில் சிறந்தவனே, நீ என்னிடம் விரும்பிய வரத்தை —”",
        '1.24': "“— உன் பரிபூரணத்துக்காக அருள்கிறேன்; உனக்கு ஞானம் உண்டாகும்.”",
        '1.25': "மார்க்கண்டேயர் கூறினார்:",
        '1.26': "இவ்வாறு அவ்விருவருக்கும் அவரவர் விரும்பிய வரத்தை அருளி,",
        '1.27': "அவர்களால் பக்தியுடன் துதிக்கப்பட்ட தேவி உடனே மறைந்தாள். இவ்வாறு தேவியிடமிருந்து வரம் பெற்ற க்ஷத்திரியர்களில் சிறந்த ஸுரதன்,",
        '1.28': "சூரியனிடமிருந்து பிறந்து ஸாவர்ணி மனுவாவான்.",
        '1.29': "இவ்வாறு ஸ்ரீமார்க்கண்டேய புராணத்தின் ஸாவர்ணிக மன்வந்தரத்தில் உள்ள தேவீ மாஹாத்ம்யத்தில் “ஸுரதனுக்கும் வணிகனுக்கும் வரமளித்தல்” என்னும் பதின்மூன்றாம் அத்தியாயம் நிறைவுற்றது.",
      },
    },
  },
};
